/*
 * Linker version script (Linux/ELF only): localize C++ standard-library
 * symbols in every extension we link. Fixes TWO production-grade crashes,
 * both caused by cross-.so interposition of the C++ runtime on Linux's flat
 * symbol namespace (macOS two-level namespaces are immune; ld64 rejects the
 * flag, so this is Linux-only via LD_EXTRA):
 *
 * 1. THE EVERY-GCS-QUERY SIGSEGV (regressed in 0.9.54, diagnosed 2026-08-06).
 *    manylinux wheels use the pre-C++11 COW string ABI. Its weak _ZNSs*
 *    member functions export at default visibility and interpose across .so,
 *    but each .so keeps its OWN _S_empty_rep_storage singleton local
 *    (--exclude-libs hides archive DATA, not our own COMDAT FUNCTIONS).
 *    Observed: pool_reader's ReadParquetMetadataFromBuffer (the GCS footer
 *    parse) calling std::string::_M_mutate BOUND INTO draken_native.so —
 *    draken's copy compares the rep against draken's singleton address,
 *    mismatches, and operator-deletes pool_reader's STATIC empty-rep:
 *    SIGSEGV in mimalloc's _ZdlPv (or free(): invalid pointer under glibc).
 *    Local parquet is unaffected (different footer path), which is why dev
 *    boxes and local benchmarks never reproduced it.
 *
 * 2. THE import-order SIGABRT: `import opteryx` then `import grpc` (via any
 *    google.cloud.*) made cygrpc bind half its std::string calls into our
 *    exported copies and half into the system libstdc++ — free(): invalid
 *    pointer at dlopen.
 *
 * Only `local:` patterns, no `global:` — unmatched symbols keep their default
 * exported binding, so PyInit_* and the RTLD_GLOBAL bridge symbols
 * (draken_vector_unwrap / draken_vector_own_raw / draken_cast_* and the
 * DecodeColumnFromChunk export _operators resolves from pool_reader) are
 * untouched. Covers BOTH string ABIs (Ss/Sb/Si/So/Sd abbreviations = old ABI,
 * _ZNSt* includes __cxx11) — never audit this by one ABI's mangling alone.
 *
 * NOTE: an earlier attempt at this script was blamed for a prod ImportError
 * (undefined draken_cast_uint_to_string) and reverted. That attribution was
 * WRONG — the ImportError came from the standalone rugo wheel overwriting
 * opteryx_core's draken/ (see the release-gate consumer-shape check), and the
 * bridge symbols demonstrably survive this script. Validate any change here
 * against a real manylinux wheel via the release gate, not a dev build alone.
 */
{
  local:
    /* pre-C++11 ABI: Ss = std::string, Sb = basic_string, Si/So/Sd = iostreams */
    _ZNSs*; _ZNKSs*;
    _ZNSbI*; _ZNKSbI*;
    _ZNSi*; _ZNKSi*;
    _ZNSo*; _ZNKSo*;
    _ZNSd*; _ZNKSd*;
    _ZTVSs; _ZTISs; _ZTSSs;
    /* std:: namespace members — includes every __cxx11 instantiation */
    _ZNSt*; _ZNKSt*; _ZNVSt*;
    _ZSt*;
    _ZTVSt*; _ZTISt*; _ZTSSt*;
    _ZTVNSt*; _ZTINSt*; _ZTSNSt*;
    /* function-local statics and their guards inside std code */
    _ZGVNSt*; _ZZNSt*; _ZGVZSt*; _ZZSt*;
    /* operator new/delete — each extension owns its static copy */
    _Znwm*; _Znam*; _ZdlPv*; _ZdaPv*;
    /* C++ runtime / unwinder (belt-and-braces; archives already hidden) */
    __cxa_*; __gxx_*; _Unwind_*; __gcc_*; __emutls*;
};
